CREATE TYPE public.app_role AS ENUM ('admin','user');
CREATE TABLE public.profiles (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, user_id uuid UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, name text NOT NULL, username text NOT NULL UNIQUE, avatar text NOT NULL DEFAULT '', bio text NOT NULL DEFAULT '', location text NOT NULL DEFAULT '', joined date NOT NULL DEFAULT current_date, preferences jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.profiles TO anon; GRANT SELECT,UPDATE ON public.profiles TO authenticated; GRANT ALL ON public.profiles TO service_role;
ALTER TABLE public.profiles ENABLE ROW LEVEL SECURITY;
CREATE POLICY profiles_public ON public.profiles FOR SELECT TO anon,authenticated USING (true);
CREATE POLICY profiles_owner_update ON public.profiles FOR UPDATE TO authenticated USING (user_id=auth.uid()) WITH CHECK (user_id=auth.uid());
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES auth.users(id) ON DELETE CASCADE, role public.app_role NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(user_id,role));
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
CREATE POLICY own_roles ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid());
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE TABLE public.museums (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, slug text NOT NULL UNIQUE, owner_id text NOT NULL REFERENCES public.profiles(id), title text NOT NULL, description text NOT NULL DEFAULT '', cover text NOT NULL DEFAULT '', category text NOT NULL DEFAULT 'Other', is_public boolean NOT NULL DEFAULT false, features jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.museums TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.museums TO authenticated; GRANT ALL ON public.museums TO service_role;
ALTER TABLE public.museums ENABLE ROW LEVEL SECURITY;
CREATE POLICY museums_public ON public.museums FOR SELECT TO anon,authenticated USING (is_public);
CREATE POLICY museums_owner ON public.museums FOR ALL TO authenticated USING (owner_id=auth.uid()::text OR public.has_role(auth.uid(),'admin')) WITH CHECK (owner_id=auth.uid()::text OR public.has_role(auth.uid(),'admin'));
CREATE TABLE public.objects (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, museum_id text NOT NULL REFERENCES public.museums(id) ON DELETE CASCADE, is_visible boolean NOT NULL DEFAULT true, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.objects TO anon; GRANT SELECT,INSERT,UPDATE,DELETE ON public.objects TO authenticated; GRANT ALL ON public.objects TO service_role;
ALTER TABLE public.objects ENABLE ROW LEVEL SECURITY;
CREATE POLICY objects_public ON public.objects FOR SELECT TO anon,authenticated USING (is_visible AND EXISTS(SELECT 1 FROM public.museums m WHERE m.id=museum_id AND m.is_public));
CREATE POLICY objects_owner ON public.objects FOR ALL TO authenticated USING (EXISTS(SELECT 1 FROM public.museums m WHERE m.id=museum_id AND (m.owner_id=auth.uid()::text OR public.has_role(auth.uid(),'admin')))) WITH CHECK (EXISTS(SELECT 1 FROM public.museums m WHERE m.id=museum_id AND (m.owner_id=auth.uid()::text OR public.has_role(auth.uid(),'admin'))));
CREATE TABLE public.dev_tasks (id text PRIMARY KEY DEFAULT gen_random_uuid()::text, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.dev_tasks TO authenticated; GRANT ALL ON public.dev_tasks TO service_role;
ALTER TABLE public.dev_tasks ENABLE ROW LEVEL SECURITY;
CREATE POLICY dev_tasks_admin ON public.dev_tasks FOR ALL TO authenticated USING (public.has_role(auth.uid(),'admin')) WITH CHECK (public.has_role(auth.uid(),'admin'));
CREATE FUNCTION public.set_updated_at() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN NEW.updated_at=now(); RETURN NEW; END $$;
CREATE TRIGGER profiles_updated BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER museums_updated BEFORE UPDATE ON public.museums FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER objects_updated BEFORE UPDATE ON public.objects FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER roles_updated BEFORE UPDATE ON public.user_roles FOR EACH ROW EXECUTE FUNCTION public.set_updated_at(); CREATE TRIGGER tasks_updated BEFORE UPDATE ON public.dev_tasks FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE FUNCTION public.handle_new_curator() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE handle text; BEGIN handle=lower(regexp_replace(coalesce(NEW.raw_user_meta_data->>'username','curator'),'[^a-zA-Z0-9_-]','','g')); IF length(handle)=0 THEN handle='curator'; END IF; IF EXISTS(SELECT 1 FROM public.profiles WHERE username=handle) THEN handle=handle||'-'||substr(NEW.id::text,1,8); END IF; INSERT INTO public.profiles(id,user_id,name,username) VALUES(NEW.id::text,NEW.id,coalesce(nullif(NEW.raw_user_meta_data->>'name',''),'Curator'),handle); RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.handle_new_curator() FROM PUBLIC;
CREATE TRIGGER on_curator_signup AFTER INSERT ON auth.users FOR EACH ROW EXECUTE FUNCTION public.handle_new_curator();
